import { Meta, StoryObj } from "@storybook/react";
import { expect, within } from "storybook/test";
import { ProductPrice } from "./product-price";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Primitives/Product Price",
  component: ProductPrice,
  parameters: {
    docs: {
      description: {
        component:
          "Formatted SEK price for product cards and steps, with an optional struck-through `previousPrice` in " +
          "front of it. `customPriceText` replaces both numbers with free text, and a missing or negative `price` " +
          "renders an empty wrapper so the layout around it stays put. Numbers are formatted with " +
          "`CurrencyHelper.formatToSek` in the current locale, which Storybook pins to Swedish.",
      },
    },
  },
  argTypes: {
    className: { table: { disable: true } },
    priceClassName: { table: { disable: true } },
    previousPriceClassName: { table: { disable: true } },
    ignoreComponentTheme: { table: { disable: true } },
  },
  args: {
    price: 299,
    previousPrice: 349,
    customPriceText: null,
  },
} satisfies Meta<typeof ProductPrice>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // Intl puts a non-breaking space between the amount and "kr", so match any whitespace.
    await expect(canvas.getByText(/^349\skr$/)).toBeVisible();
    await expect(canvas.getByText(/^299\skr$/)).toBeVisible();
  },
};

export const VariantRendering: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="Price combinations (price, previousPrice, customPriceText)" variantType="other">
      <Variant label="price only">
        <ProductPrice {...args} previousPrice={undefined} />
      </Variant>
      <Variant label="price + previousPrice (struck through)">
        <ProductPrice {...args} />
      </Variant>
      <Variant label='price 0 (renders "0 kr")'>
        <ProductPrice {...args} price={0} previousPrice={undefined} />
      </Variant>
      <Variant label="customPriceText (replaces the numbers)">
        <ProductPrice {...args} customPriceText="Från 299 kr" />
      </Variant>
      <Variant label="previousPrice without price (renders an empty wrapper)">
        <ProductPrice {...args} price={undefined} />
      </Variant>
    </ShowcaseLayout>
  ),
};
