import { CurrencyHelper, multipleClassNames } from "@/core/helpers";
import styles from "./product-price.module.less";
import { isNumber } from "lodash-es";

type ProductPriceProps = {
  /** Current price in SEK. Rendered with `CurrencyHelper.formatToSek` when it is a number of at least 0; otherwise nothing is shown. */
  price?: number;
  /** Earlier price in SEK, rendered struck through before the current price. Only shown together with a valid `price`. */
  previousPrice?: number;
  className?: string;
  priceClassName?: string;
  previousPriceClassName?: string;
  /** Free text shown instead of the formatted prices, e.g. "Från 299 kr" or "Ingår". Pass null to show the prices. */
  customPriceText: string | null;
  /** Intended to opt out of component theming on the wrapper.
   * @deprecated The stylesheet defines no rule for it today, so it has no visible effect. */
  ignoreComponentTheme?: boolean;
};

export const ProductPrice = ({
  price,
  previousPrice,
  className,
  priceClassName,
  previousPriceClassName,
  customPriceText,
  ignoreComponentTheme,
}: ProductPriceProps) => {
  const isPriceValid = isNumber(price) && price >= 0;
  const isPreviousPriceValid = isNumber(previousPrice) && previousPrice > -1;

  return (
    <span className={multipleClassNames(className, !ignoreComponentTheme && styles.activeComponentTheme)}>
      {customPriceText ? (
        <span className={multipleClassNames(styles.price, priceClassName)}>{customPriceText}</span>
      ) : (
        <>
          {isPriceValid && isPreviousPriceValid && (
            <span className={multipleClassNames(styles.previousPrice, previousPriceClassName)}>
              {CurrencyHelper.formatToSek(previousPrice)}
            </span>
          )}
          {isPriceValid && (
            <span className={multipleClassNames(styles.price, priceClassName)}>
              {CurrencyHelper.formatToSek(price)}
            </span>
          )}
        </>
      )}
    </span>
  );
};
